const labels={admin:'Administrador',worker:'Trabajador',wholesale:'Mayorista',pending:'Pendiente',review:'En revisión',available:'Disponible',reserved:'Reservada',sold:'Entregada',purged:'Datos eliminados',rejected:'Rechazada',delivered:'Entregado',expired:'Vencido',cancelled:'Cancelado',open:'Abierto',escalated:'Derivado al administrador',resolved:'Resuelto',paid:'Pagado'};
