async function api(url,body){const writing=body!==undefined;if(writing){activeWrites++;stateSequence++;}try{const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok){if(r.status===401&&url!=='/api/login'){S=null;login();}throw Error(d.error||'No se pudo completar la operación');}return d;}finally{if(writing){activeWrites--;flushLiveQueue();}}}
function toast(text){$('#toast').className='toast';$('#toast').textContent=text;setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},5500);}
async function load(){const sequence=++stateSequence,signals=liveSignals;const next=await api('/api/state');if(sequence!==stateSequence)return;S=next;stateStamp=snapshotStamp(next);liveQueued=null;livePending=liveSignals!==signals;render();startLiveSync();}
async function command(action,payload){await api('/api/command',{action,payload});await load();toast('Operación guardada correctamente');}
function theme(name){name=themeCatalog[name]?name:'original';const data=themeCatalog[name];document.body.className='theme-'+name;document.body.dataset.arkaTheme=name;const greeting=document.querySelector('.season-greeting');if(greeting)greeting.textContent=data.greeting;window.dispatchEvent(new CustomEvent('arka:theme',{detail:{name}}));const season=$('#season');season.innerHTML='';if(name==='original')return;const count=name==='easter'?15:30;for(let i=0;i<count;i++){const el=document.createElement('span');el.className='particle';el.textContent=data.particles[i%data.particles.length];el.style.cssText='left:'+Math.random()*100+'%;font-size:'+(name==='easter'?10+Math.random()*8:12+Math.random()*13)+'px;animation-duration:'+(14+Math.random()*18)+'s;animation-delay:-'+Math.random()*25+'s;color:'+data.color;season.append(el);}}
function advertise(){clearInterval(adTimer);$('.flying-ad')?.remove();if(!S||(role()!=='wholesale'&&!isStorePreview())||!S.settings.announcement_enabled||!S.settings.announcement)return;const fly=()=>{if($('.modal-backdrop')||document.hidden)return;const el=document.createElement('div');el.className='flying-ad';el.setAttribute('aria-hidden','true');el.innerHTML='<div class="balloon"></div><div class="balloon-basket"></div><div class="ad-message">'+esc(S.settings.announcement)+'</div>';document.body.append(el);setTimeout(()=>el.remove(),21500);};setTimeout(()=>{if(S&&(role()==='wholesale'||isStorePreview()))fly();},6000);adTimer=setInterval(fly,Math.max(25,S.settings.announcement_interval)*1000);}
function login(){staffSearchTerms={};stopLiveSync();S=null;$('#modal-root').innerHTML='';modalDetail=null;modalVersion++;toggleDrawer(false);clearInterval(adTimer);$('.flying-ad')?.remove();$('#app').innerHTML='<main class="login"><section class="login-story"><div class="brand"><span class="brand-mark"></span>ARKA <small>DIGITAL</small></div><div><div class="eyebrow">ENTRETENIMIENTO SIN LÍMITES</div><h1>Todo el streaming.<br><span class="gradient-text">Todas las<br>posibilidades.</span></h1><p>Tu centro de operaciones para un negocio digital conectado, organizado y siempre en movimiento.</p><div class="stream-tiles"><span style="color:#4da5f8">prime</span><span style="color:#ee4261">N</span><span style="color:#bfa5ff">max</span><span style="color:#5fa4ff">D+</span></div></div><small class="muted">ARKA DIGITAL · Plataforma privada de distribución</small></section><section class="login-form"><div class="season-greeting">❄ Navidad en ARKA DIGITAL</div><div class="eyebrow">BIENVENIDO A ARKA</div><h2>Tu negocio, conectado.</h2><p class="muted" style="font-size:13px">Ingresa con los datos que te proporcionó el administrador.</p><form id="login-form"><label class="field">Correo electrónico<input name="email" type="email" placeholder="tu@correo.com" autocomplete="username" required></label><label class="field">Contraseña<input name="password" type="password" placeholder="Tu contraseña" autocomplete="current-password" required></label><div id="login-error"></div><button class="primary" type="submit">Ingresar a mi panel &nbsp; →</button></form><p class="login-foot muted">Acceso exclusivo para mayoristas y equipo de trabajo.<br>¿Necesitas una cuenta? Contacta al administrador.</p></section></main>';const greeting=$('.season-greeting');if(greeting)greeting.textContent=(themeCatalog[document.body.dataset.arkaTheme]||themeCatalog.original).greeting;$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/login',Object.fromEntries(new FormData(e.target)));view='home';await load();}catch(err){$('#login-error').innerHTML='<div class="error">'+esc(err.message)+'</div>';}finally{button.disabled=false;}};}
const navs={wholesale:[['home','◈','Tienda mayorista'],['orders','▤','Mis pedidos'],['purchases','▦','Mis productos'],['reports','◉','Reportes y garantías']],worker:[['home','◈','Mi resumen'],['assignments','▤','Mis asignaciones'],['upload','↑','Subir cuentas'],['production','▦','Mi producción'],['rejected','!','Cuentas rechazadas'],['reports','◉','Garantías por resolver'],['wallet','＄','Mi saldo y retiros']],admin:[['home','◈','Resumen general'],['label','COMPRAS Y MAYORISTAS'],['store-preview','◈','Ver mi tienda'],['wholesalers','♙','Mayoristas'],['products','▦','Productos y ofertas'],['inventory','▥','Stock y cuentas'],['orders','▤','Pagos y pedidos'],['banks','▣','Cuentas bancarias'],['reports','◉','Reportes y garantías'],['appearance','✦','Apariencia'],['label','EQUIPO Y PRODUCCIÓN'],['workers','♙','Trabajadores'],['assignments','▤','Asignar trabajo'],['reviews','✓','Productos por revisión'],['credits','＄','Pagos y saldos'],['withdrawals','↗','Retiros solicitados']]};
function toggleDrawer(force){const sidebar=$('.sidebar');if(!sidebar)return;const open=typeof force==='boolean'?force:!sidebar.classList.contains('open');sidebar.classList.toggle('open',open);let back=$('.drawer-backdrop');if(!back){back=document.createElement('div');back.className='drawer-backdrop';back.setAttribute('aria-hidden','true');back.addEventListener('click',()=>toggleDrawer(false));document.body.append(back);}back.classList.toggle('open',open);$('.mobile-menu')?.setAttribute('aria-expanded',String(open));}
function render(){toggleDrawer(false);theme(S.settings.theme);const list=navs[role()];$('#app').innerHTML='<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark"></span>ARKA <small>DIGITAL</small></div><div class="nav-label">MI ESPACIO</div><nav>'+list.map(n=>n[0]==='label'?'<div class="nav-label">'+n[1]+'</div>':'<button class="nav-btn '+(view===n[0]?'active':'')+'" data-nav="'+n[0]+'"><span class="nav-icon">'+n[1]+'</span>'+n[2]+'</button>').join('')+'</nav><div class="sidebar-foot">'+esc(labels[role()])+'<br><br>'+btn('Cambiar contraseña','password','','ghost small')+'<p>© '+new Date().getFullYear()+' ARKA DIGITAL</p></div></aside><section class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Abrir menú">☰</button><div class="breadcrumb">Mi espacio &nbsp; / &nbsp; <strong>'+esc(list.find(n=>n[0]===view)?.[2]||'Panel')+'</strong></div><div class="top-actions">'+(role()==='admin'?btn(isStorePreview()?'Volver a mi panel':'Ver mi tienda',isStorePreview()?'store-back':'store-preview','','ghost small'):'')+(role()==='wholesale'?btn('Bolsa · '+Object.values(cart).reduce((a,b)=>a+b,0),'cart','','ghost small'):'')+'<div class="profile"><span class="avatar">'+esc(S.user.name.slice(0,2).toUpperCase())+'</span><div>'+esc(S.user.name)+'<small>'+esc(labels[role()])+'</small></div></div>'+btn('Salir','logout','','ghost small')+'</div></header><main class="content" id="content"></main></section></div>';renderContent();advertise();}
function head(title,sub='',actions=''){return '<div class="page-head"><div><span class="eyebrow">ARKA DIGITAL / '+esc(labels[role()])+'</span><h1>'+title+'</h1><p>'+sub+'</p></div><div>'+actions+'</div></div>';}
function empty(title,sub='Los registros aparecerán aquí cuando estén disponibles.'){return '<div class="empty"><div class="empty-icon">◇</div><h3>'+esc(title)+'</h3>'+esc(sub)+'</div>';}
function table(headers,rows){return rows.length?'<div class="table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((c,i)=>'<td class="'+(i===0?'wrap':'')+'">'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':empty('Todavía no hay registros');}
