 if(view==='home'){h=head(admin?'Todo bajo control.':'Hola, '+esc(S.user.name.split(' ')[0])+'.',admin?'Gestiona tu tienda, tu equipo y cada entrega desde un solo lugar.':'Tu trabajo, tus cuentas y tus ganancias en un solo lugar.');if(admin){h+='<div class="metrics">'+metric('Ventas entregadas',money(S.orders.filter(o=>o.status==='delivered').reduce((t,o)=>t+Number(o.total_cents),0)))+metric('Stock disponible',S.accounts.filter(a=>a.status==='available').length,'▦')+metric('Cuentas por revisar',S.accounts.filter(a=>a.status==='review').length,'✓')+metric('Retiros pendientes',S.withdrawals.filter(w=>w.status==='pending').length,'＄')+'</div><div class="two-cols">'+panel('Pagos por verificar',table(['Pedido','Total','Acción'],S.orders.filter(o=>o.status==='review').slice(0,6).map(o=>[esc(uname(o.buyer_id)),money(o.total_cents),btn('Revisar','order',o.id)])))+panel('Actividad de producción',table(['Producto','Estado','Acción'],S.accounts.filter(a=>a.status==='review').slice(0,6).map(a=>[esc(pname(a.product_id)),badge(a.status),btn('Revisar','account',a.id)])))+'</div>';}else{h+='<div class="metrics">'+metric('Saldo disponible',money(S.user.balance_cents-S.user.reserved_cents),'＄')+metric('Cuentas aprobadas',S.accounts.filter(a=>a.paid).length,'✓')+metric('Pendientes de revisión',S.accounts.filter(a=>a.status==='review').length,'▦')+metric('Garantías pendientes',S.reports.filter(r=>r.status==='open').length,'◉')+'</div>'+panel('Tus asignaciones',assignmentsTable());}}
 else if(view==='products'){h=head('Productos y ofertas','El producto conecta la oferta, las asignaciones y el stock sin depender del título.',btn('+ Nuevo producto','product-new','','primary'));h+=panel('',table(['Producto','Modalidad','Precio','Stock','Estado','Acción'],S.products.map(p=>[esc(p.name),p.mode==='domain'?'A dominio':p.duration_months+' meses / '+p.duration_days+' días',money(p.price_cents),stock(p.id),p.active?'Activo':'Oculto',btn('Editar','product-edit',p.id)])));}
 else if(['wholesalers','workers'].includes(view)){const worker=view==='workers';h=head(worker?'Trabajadores':'Mayoristas',worker?'Controla la producción, las cuentas generadas y los saldos.':'Crea y administra el acceso privado de tus compradores.',btn('+ Registrar '+(worker?'trabajador':'mayorista'),worker?'worker-new':'wholesale-new','','primary'));h+=panel('',table(['Nombre / correo','Teléfono','Estado',...(worker?['Saldo']:[]),'Acciones'],S.users.filter(u=>!u.deleted_at&&u.role===(worker?'worker':'wholesale')).map(u=>[esc(u.name)+'<br><span class="muted">'+esc(u.email)+'</span>',esc(u.phone),u.active?'Activo':'Suspendido',...(worker?[money(u.balance_cents)]:[]),btn('Editar','user-edit',u.id)+(worker?btn('Ver producción','worker-profile',u.id):'')+btn(u.active?'Suspender':'Reactivar',u.active?'user-suspend':'user-activate',u.id)+btn('Eliminar','user-delete',u.id,'danger')])));}
 else if(view==='banks'){h=head('Cuentas bancarias','Estos datos se muestran al mayorista cuando va a pagar.',btn('+ Añadir banco','bank-new','','primary'));h+=panel('',table(['Banco','Titular','Número','Estado','Acción'],S.banks.map(b=>[esc(b.bank),esc(b.holder),esc(b.account_number),b.active?'Activo':'Oculto',btn('Editar','bank-edit',b.id)])));}
 else if(view==='assignments'){h=head(admin?'Asignar trabajo':'Mis asignaciones','Cada asignación conserva la cantidad y la tarifa acordadas.',admin?btn('+ Asignar producto','assignment-new','','primary'):btn('Subir cuentas','go-upload','','primary'));h+=panel('',assignmentsTable());}
 else if(view==='upload'){h=head('Subir cuentas','Carga solo los productos que tienes asignados. Cada cuenta incluye correo, contraseña y observación.');h+=panel('Nueva carga',uploadForm(false));}
 else if(['inventory','reviews','production','rejected'].includes(view)){const titles={inventory:'Stock y cuentas',reviews:'Productos por revisión',production:'Mi producción',rejected:'Cuentas rechazadas'};h=head(titles[view],view==='reviews'?'Aprobar añade stock y acredita una sola vez la tarifa del trabajador.':'Las cuentas permanecen vinculadas a su producto y responsable.',view==='inventory'?btn('+ Cargar stock propio','stock-new','','primary'):'');let accounts=S.accounts.filter(a=>view==='reviews'?a.status==='review':view==='rejected'?a.status==='rejected':true);h+=panel('',staffAccountSection(view));}
 else if(view==='orders'){h=head(admin?'Pagos y pedidos':'Mis pedidos',admin?'Verifica el ingreso real en tu banco antes de aprobar.':'La entrega quedará disponible aunque cierres la web.');h+=panel('',table(['Pedido / fecha',...(admin?['Mayorista']:[]),'Total','Estado','Acción'],S.orders.sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(o=>['#'+o.id.slice(0,8)+'<br><span class="muted">'+date(o.created_at)+'</span>',...(admin?[esc(uname(o.buyer_id))]:[]),money(o.total_cents),badge(o.status),btn(admin?'Revisar':'Ver pedido','order',o.id)+(admin&&['rejected','cancelled','expired'].includes(o.status)?btn('Eliminar','order-delete',o.id,'danger small'):'')])));}
 else if(view==='purchases'){h=head('Mis productos','Tus compras organizadas por producto y fecha. Nunca mezclamos plataformas.');const groups=S.items.filter(i=>S.orders.find(o=>o.id===i.order_id)?.status==='delivered');h+=groups.length?groups.map(i=>{const o=S.orders.find(o=>o.id===i.order_id);return '<div class="purchase-group"><div><h4>'+esc(i.product_name)+'</h4><p>'+i.quantity+' cuentas · '+date(o.delivered_at)+' · #'+o.id.slice(0,8)+'</p></div>'+btn('Ver mis productos','purchase',i.id)+'</div>';}).join(''):panel('',empty('Aún no tienes productos','Al aprobar tu pago, aparecerán aquí separados por producto y fecha.'));}
 else if(view==='reports'){h=head(admin?'Reportes y garantías':role()==='worker'?'Garantías por resolver':'Mis reportes',role()==='worker'?'Las correcciones y reemplazos no generan pagos adicionales.':'Los reportes cerrados pueden eliminarse; los datos corregidos de la cuenta se conservan.');h+=panel('',role()==='wholesale'?reportsTable(S.reports):staffReportSection());}
 else if(view==='wallet'){h=head('Mi saldo y retiros','Solicita desde $10. Los importes pendientes quedan reservados.');h+='<div class="balance-card"><small>SALDO DISPONIBLE</small><strong>'+money(S.user.balance_cents-S.user.reserved_cents)+'</strong><p>Reservado: '+money(S.user.reserved_cents)+' · Saldo total: '+money(S.user.balance_cents)+'</p>'+btn('Solicitar retiro','withdraw','','ghost')+'</div>'+panel('Mis retiros',withdrawalsTable())+panel('Movimientos',ledgerTable(S.ledger));}
 else if(view==='withdrawals'){h=head('Retiros solicitados','Confirma solo después de transferir. Rechazar libera el saldo reservado.');h+=panel('',withdrawalsTable());}
 else if(view==='credits'){h=head('Pagos y saldos','La producción aprobada se acredita automáticamente. Los abonos manuales quedan registrados.',btn('+ Acreditar fondos','credit','','primary'));h+=panel('Saldos del equipo',table(['Trabajador','Saldo total','Reservado','Disponible'],S.users.filter(u=>u.role==='worker').map(u=>[esc(u.name),money(u.balance_cents),money(u.reserved_cents),money(u.balance_cents-u.reserved_cents)])))+panel('Movimientos',ledgerTable(S.ledger));}
 else if(view==='appearance'){h=head('Una tienda con tu estilo.','Cambia toda la ambientación sin modificar productos ni pedidos.');h+=panel('Temas de ARKA DIGITAL','<div class="theme-options">'+Object.entries(themeCatalog).map(([id,t])=>[id,t.icon,t.label]).map(t=>'<button class="theme-option '+(S.settings.theme===t[0]?'active':'')+'" data-action="theme" data-id="'+t[0]+'"><span>'+t[1]+'</span>'+t[2]+'</button>').join('')+'</div>');h+=panel('Anuncio en globo aerostático','<p class="subtle">Un globo cruza la tienda periódicamente sin bloquear las compras. Las animaciones respetan la preferencia de movimiento reducido.</p>'+btn('Configurar anuncio y contacto','settings','','primary'));}
 else h=empty('Selecciona una sección');$('#content').innerHTML=h;
 if(view==='upload')bindUpload(false);
