function isStorePreview(){return role()==='admin'&&view==='store-preview';}
function shopProducts(){return S.products.filter(p=>p.active!==false);}
function shop(){const cats=['Todos',...new Set(shopProducts().map(p=>p.category))];$('#content').innerHTML=(isStorePreview()?'<div class="notice"><strong>Vista previa de tu tienda</strong> · Catálogo tal como lo ven tus mayoristas. Sigues como administrador; aquí no se generan compras.</div>':'')+'<section class="hero"><div><div class="eyebrow">TU ALIADO EN ENTRETENIMIENTO DIGITAL</div><h1>Más streaming.<br><span class="gradient-text">Más posibilidades.</span></h1><p>Tus plataformas favoritas, en un solo lugar.<br>Elige, compra y haz crecer tu negocio con ARKA DIGITAL.</p><span class="tag">EXCLUSIVO PARA MAYORISTAS</span></div><div class="hero-art"><span style="color:#72c4ff">P</span><span>N</span><span style="color:#cbb5ff">max</span></div></section><div class="toolbar"><input class="search" id="search-products" placeholder="⌕ Buscar plataforma o producto…" value="'+esc(query)+'">'+cats.map(c=>'<button class="chip '+(category===c?'active':'')+'" data-category="'+esc(c)+'">'+esc(c)+'</button>').join('')+'</div><div class="section-title">Explora nuestro catálogo <small id="product-count"></small></div><div class="product-grid" id="product-grid"></div><p class="subtle" style="text-align:center;margin-top:30px">Acceso privado · Pagos verificados · Compras organizadas · Garantías con seguimiento</p>';productGrid();$('#search-products').oninput=e=>{query=e.target.value;productGrid();};}
function productGrid(){const products=shopProducts().filter(p=>(category==='Todos'||p.category===category)&&(p.name+' '+p.description).toLowerCase().includes(query.toLowerCase()));$('#product-count').textContent=products.length+' productos';$('#product-grid').innerHTML=products.length?products.map(p=>'<article class="product-card" style="--brand:'+esc(p.color)+'"><div class="product-visual"><div class="product-logo">'+(p.image_url?'<img src="'+esc(p.image_url)+'" alt="'+esc(p.brand)+'">':esc(p.brand))+'</div></div><div class="product-body"><div class="product-top"><h3>'+esc(p.name)+'</h3><span class="tag">'+(p.mode==='domain'?'A dominio':p.duration_months?p.duration_months+' '+(p.duration_months===1?'mes':'meses'):p.duration_days+' días')+'</span></div><p>'+esc(p.description||'Consulta los detalles y las condiciones de este producto.')+'</p><div class="stock '+(!stock(p.id)?'empty-stock':'')+'">'+(stock(p.id)?stock(p.id)+' disponibles':'Sin stock por ahora')+'</div><div class="product-bottom"><span class="price">'+money(p.price_cents)+' <small>/ cuenta</small></span><button class="primary small" data-action="buy" data-id="'+p.id+'" '+(!stock(p.id)?'disabled':'')+'>Comprar &nbsp; +</button></div>'+btn('Ver detalles y garantía','product-details',p.id,'details')+'</div></article>').join(''):'<div style="grid-column:1/-1">'+panel('',empty('Estamos preparando el catálogo','Los productos aparecerán aquí cuando el administrador los publique.'))+'</div>';}
async function showPurchase(id,refresh=false){const expectedVersion=modalVersion,expectedView=view,item=S.items.find(row=>row.id===id);if(!item)return;const result=await api('/api/orders/'+encodeURIComponent(item.order_id)+'/accounts?product_id='+encodeURIComponent(item.product_id));if(!S||modalVersion!==expectedVersion||view!==expectedView||(refresh&&(modalDetail?.type!=='purchase'||modalDetail.id!==id)))return;const previousSearch=refresh?$('#purchase-search'):null,query=previousSearch?.value||(refresh?modalDetail?.query:'')||'',focused=!!previousSearch&&document.activeElement===previousSearch,selection=focused?[previousSearch.selectionStart,previousSearch.selectionEnd]:null,accounts=result.accounts;const html='<div class="toolbar"><label class="field" style="flex:1 1 240px;min-width:0"><span>⌕ Buscar por correo electrónico</span><input id="purchase-search" class="search" type="search" aria-label="Buscar cuenta por correo" placeholder="Escribe el correo completo o una parte…" autocomplete="off" value="'+esc(query)+'"></label><span class="subtle" id="purchase-count" role="status" aria-live="polite"></span></div><div id="purchase-accounts"></div>';modal(esc(item.product_name)+' · '+accounts.length+' cuentas',html,null,true,{type:'purchase',id,query});const input=$('#purchase-search'),draw=()=>{const term=input.value.trim().toLowerCase(),matches=accounts.filter(account=>!term||(account.email||'').toLowerCase().includes(term));$('#purchase-count').textContent=matches.length+' de '+accounts.length+' cuentas';$('#purchase-accounts').innerHTML=matches.length?accountsTable(matches,true):empty('No se encontraron cuentas con ese correo','Prueba con una parte del correo o borra la búsqueda.');if(modalDetail?.type==='purchase'&&modalDetail.id===id)modalDetail.query=input.value;};input.oninput=draw;draw();if(focused){input.focus({preventScroll:true});input.setSelectionRange(...selection);}}
function assignmentRemaining(assignment){return Math.max(0,Number(assignment.quantity)-S.accounts.filter(account=>account.assignment_id===assignment.id).length);}
function assignmentsTable(){return table([...(role()==='admin'?['Trabajador']:[]),'Producto','Cantidad','Entregadas','Tarifa / cuenta','Pendientes'],S.assignments.map(a=>{const rows=S.accounts.filter(c=>c.assignment_id===a.id);return [...(role()==='admin'?[esc(uname(a.worker_id))]:[]),esc(pname(a.product_id)),a.quantity,rows.length,money(a.rate_cents),assignmentRemaining(a)];}));}
function staffAccountRows(key){if(key.startsWith('worker:'))return S.accounts.filter(account=>account.worker_id===key.slice(7));return S.accounts.filter(account=>key==='reviews'?account.status==='review':key==='rejected'?account.status==='rejected':true);}
function staffMatches(rows,key,emailOf=row=>row.email){const term=(staffSearchTerms[key]||'').trim().toLowerCase();return rows.filter(row=>!term||(emailOf(row)||'').toLowerCase().includes(term));}
function staffSearchControls(key,found,total){return '<div class="toolbar"><label class="field" style="flex:1 1 240px;min-width:0"><span>⌕ Buscar por correo electrónico</span><input class="search" type="search" data-staff-search="'+esc(key)+'" aria-label="Buscar por correo electrónico" placeholder="Escribe el correo completo o una parte…" autocomplete="off" value="'+esc(staffSearchTerms[key]||'')+'"></label><span class="subtle" style="color:var(--purchase-muted,#55536c)" data-staff-count="'+esc(key)+'" role="status" aria-live="polite">'+found+' de '+total+' registros</span></div>';}
function staffAccountSection(key){const rows=staffAccountRows(key),matches=staffMatches(rows,key);return staffSearchControls(key,matches.length,rows.length)+'<div data-staff-results="'+esc(key)+'">'+(matches.length?accountsTable(matches,true):empty('No se encontraron cuentas con ese correo','Borra la búsqueda para ver todas las cuentas disponibles en esta sección.'))+'</div>';}
function reportsTable(reports){const staff=role()!=='wholesale',admin=role()==='admin';return table(['Producto / problema',...(staff?['Correo electrónico']:[]),...(admin?['Responsable']:[]),'Fecha','Estado','Acción'],reports.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(report=>{const account=S.accounts.find(account=>account.id===report.account_id);return[esc(pname(account?.product_id))+'<br><span class="muted">'+esc(report.problem.slice(0,100))+'</span>',...(staff?[esc(account?.email||'Datos de acceso eliminados')]:[]),...(admin?[esc(uname(report.worker_id))]:[]),date(report.created_at),badge(report.status),btn('Ver reporte','report',report.id)+(admin&&['resolved','rejected'].includes(report.status)?btn('Eliminar','report-delete',report.id,'danger small'):'')];}));}
function staffReportSection(){const matches=staffMatches(S.reports,'reports',report=>S.accounts.find(account=>account.id===report.account_id)?.email);return staffSearchControls('reports',matches.length,S.reports.length)+'<div data-staff-results="reports">'+(matches.length?reportsTable(matches):empty('No se encontraron reportes con ese correo','Borra la búsqueda para ver todos los reportes de esta sección.'))+'</div>';}
function updateStaffSearch(key){const target=[...document.querySelectorAll('[data-staff-results]')].find(node=>node.dataset.staffResults===key),counter=[...document.querySelectorAll('[data-staff-count]')].find(node=>node.dataset.staffCount===key);if(!target)return;const reports=key==='reports',rows=reports?S.reports:staffAccountRows(key),matches=staffMatches(rows,key,reports?report=>S.accounts.find(account=>account.id===report.account_id)?.email:row=>row.email);target.innerHTML=matches.length?(reports?reportsTable(matches):accountsTable(matches,true)):empty(reports?'No se encontraron reportes con ese correo':'No se encontraron cuentas con ese correo','Prueba con una parte del correo o borra la búsqueda.');if(counter)counter.textContent=matches.length+' de '+rows.length+' registros';}
document.addEventListener('input',event=>{const input=event.target.closest('[data-staff-search]');if(!input)return;staffSearchTerms[input.dataset.staffSearch]=input.value;updateStaffSearch(input.dataset.staffSearch);});
function accountsTable(accounts,withEmail=false){return table(['Producto',...(withEmail?['Correo electrónico']:[]),...(role()==='admin'?['Trabajador','Comprador']:[]),'Estado','Fecha','Vencimiento','Acción'],accounts.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(a=>[esc(pname(a.product_id))+(a.reason?'<br><span class="muted">'+esc(a.reason)+'</span>':''),...(withEmail?[esc(a.email||'Datos de acceso eliminados')]:[]),...(role()==='admin'?[esc(uname(a.worker_id)),esc(uname(a.buyer_id))]:[]),badge(a.status),date(a.delivered_at||a.created_at),date(a.expires_at),btn('Ver cuenta','account',a.id)+(role()==='worker'&&a.status==='rejected'?btn('Corregir','resubmit',a.id):'')]));}
function withdrawalsTable(){return table([...(role()==='admin'?['Trabajador']:[]),'Importe','Banco / cuenta','Titular','Estado','Fecha','Acción'],S.withdrawals.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(w=>[...(role()==='admin'?[esc(uname(w.worker_id))]:[]),money(w.amount_cents),esc(w.bank)+'<br>'+esc(w.account_number),esc(w.holder),badge(w.status)+(w.reason?'<br>'+esc(w.reason):''),date(w.created_at),role()==='admin'&&w.status==='pending'?btn('Confirmar pago','withdraw-paid',w.id,'success small')+btn('Rechazar','withdraw-reject',w.id,'danger small'):'—']));}
function ledgerTable(rows){return table(['Fecha',...(role()==='admin'?['Trabajador']:[]),'Movimiento','Importe'],rows.slice().sort((a,b)=>b.created_at.localeCompare(a.created_at)).map(l=>[date(l.created_at),...(role()==='admin'?[esc(uname(l.worker_id))]:[]),esc(l.note||l.kind),'<span style="color:'+(l.amount_cents<0?'#d34b65':'#219b72')+'">'+money(l.amount_cents)+'</span>']));}
function field(name,label,value='',type='text',options=null,required=true){if(type==='select')return '<label class="field">'+label+'<select name="'+name+'" '+(required?'required':'')+'>'+options.map(o=>'<option value="'+esc(o[0])+'" '+(String(value)===String(o[0])?'selected':'')+'>'+esc(o[1])+'</option>').join('')+'</select></label>';if(type==='textarea')return '<label class="field">'+label+'<textarea name="'+name+'" '+(required?'required':'')+'>'+esc(value)+'</textarea></label>';if(type==='checkbox')return '<label class="checkbox"><input type="checkbox" name="'+name+'" '+(value?'checked':'')+'>'+label+'</label>';return '<label class="field">'+label+'<input type="'+type+'" name="'+name+'" value="'+esc(value)+'" '+(required?'required':'')+(type==='number'?' step="0.01" min="0"':'')+(type==='password'?' autocomplete="new-password"':'')+'></label>';}
function modal(title,html,onSave=null,wide=false,detail=null){modalDetail=detail;modalVersion++;lastFocus=document.activeElement;modalSave=onSave;$('#modal-root').innerHTML='<div class="modal-backdrop"><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="modal-head"><h2>'+title+'</h2><button data-action="close" aria-label="Cerrar">×</button></div>'+(onSave?'<form id="modal-form">'+html+'<div id="form-error"></div><div class="modal-footer">'+btn('Cancelar','close','','ghost')+'<button type="submit" class="primary">Guardar</button></div></form>':html)+'</section></div>';$('#modal-root').querySelector('input,select,textarea,button')?.focus();if(onSave)$('#modal-form').onsubmit=async e=>{e.preventDefault();activeActions++;const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));e.target.querySelectorAll('input[type=checkbox]').forEach(c=>d[c.name]=c.checked);await onSave(d);closeModal();}catch(err){const target=$('#form-error');if(target)target.innerHTML='<div class="error">'+esc(err.message)+'</div>';else toast(err.message);}finally{submit.disabled=false;activeActions--;flushLiveQueue();}};}
function closeModal(){$('#modal-root').innerHTML='';modalSave=null;modalDetail=null;modalVersion++;lastFocus?.focus?.();flushLiveQueue();}
async function saveAdmin(kind,data){await api('/api/admin/'+kind,data);await load();toast('Cambios guardados');}
function uploadForm(own){const opts=own?S.products.map(p=>[p.id,p.name]):S.assignments.filter(a=>a.active&&assignmentRemaining(a)>0).map(a=>[a.id,pname(a.product_id)+' · '+assignmentRemaining(a)+' pendiente'+(assignmentRemaining(a)===1?'':'s')+' de '+a.quantity]);if(!own&&!opts.length)return empty('No tienes nuevas cargas pendientes','Las asignaciones ya enviadas o completadas no aparecen aquí. Si tienes cuentas rechazadas, corrígelas desde «Cuentas rechazadas»; no las subas como una carga nueva.');return '<form id="upload-form">'+field(own?'product_id':'assignment_id',own?'Producto':'Asignación','', 'select',opts)+'<div class="notice" style="margin:15px 0">Una cuenta por línea con el formato:<br><strong>correo | contraseña | observación para el comprador</strong><br>La observación también se entrega al mayorista. No incluyas notas internas. Máximo 1000 por envío.</div>'+field('lines','Cuentas','','textarea')+'<div id="upload-error"></div><button type="submit" class="primary" style="margin-top:15px">'+(own?'Añadir al stock':'Enviar a revisión')+'</button></form>';}
function bindUpload(own){const form=$('#upload-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();activeActions++;const submit=e.target.querySelector('button');submit.disabled=true;try{const d=Object.fromEntries(new FormData(e.target)),accounts=d.lines.split(/\r?\n/).filter(l=>l.trim()).map(l=>{const parts=l.split('|');return {email:parts.shift()?.trim(),password:parts.shift()?.trim(),observation:parts.join('|').trim()};});if(!own){const assignment=S.assignments.find(a=>a.id===d.assignment_id&&a.active);if(!assignment||assignmentRemaining(assignment)===0)throw Error('Esta asignación ya está completa. Actualiza la página para ver las pendientes.');if(accounts.length>assignmentRemaining(assignment))throw Error('Solo faltan '+assignmentRemaining(assignment)+' cuentas por subir en esta asignación.');}await command('submit_accounts',{[own?'product_id':'assignment_id']:d[own?'product_id':'assignment_id'],accounts});if(own)closeModal();}catch(err){const target=$('#upload-error');if(target)target.innerHTML='<div class="error">'+esc(err.message)+'</div>';else toast(err.message);}finally{submit.disabled=false;activeActions--;flushLiveQueue();}};}
async function showAccount(id,refresh=false){const expectedVersion=modalVersion;const a=S.accounts.find(x=>x.id===id);const details=await api('/api/accounts/'+id);if(refresh&&(modalVersion!==expectedVersion||modalDetail?.type!=='account'||modalDetail.id!==id))return;let html='<p class="subtle">'+esc(pname(a.product_id))+' · '+badge(a.status)+'</p>'+credential(details.data)+'<p class="subtle">Entrega: '+date(a.delivered_at)+'<br>Vencimiento / fin de garantía: '+date(a.expires_at)+(a.confirmed_at?'<br>Confirmada: '+date(a.confirmed_at):'')+'</p>';if(a.reason)html+='<div class="error">'+esc(a.reason)+'</div>';html+='<div class="row-actions">';if(role()==='admin'&&a.status==='review')html+=btn('Aprobar cuenta','approve-account',id,'success')+btn('Rechazar','reject-account',id,'danger');if(role()==='admin')html+=btn('Ver historial','account-history',id);if(role()==='worker'&&a.status==='rejected')html+=btn('Corregir y reenviar','resubmit',id,'primary');if(role()==='wholesale'&&a.status==='sold'){html+=btn('Reportar un problema','report-new',id,'danger small');if(S.products.find(p=>p.id===a.product_id)?.mode==='domain'&&!a.confirmed_at)html+=btn('Funciona y cambié el correo','confirm-account',id,'success small');}html+='</div>';modal('Datos de la cuenta',html,null,false,{type:'account',id});}
function credential(d){return d?'<div class="account-data"><label>CORREO</label><code>'+esc(d.email)+'</code><label>CONTRASEÑA</label><code>'+esc(d.password)+'</code><label>OBSERVACIÓN PARA EL COMPRADOR</label><code>'+esc(d.observation||'Sin observaciones')+'</code></div>':'<div class="notice">Los datos de acceso fueron eliminados según la política de conservación. El registro de la operación se mantiene.</div>';}
function showOrder(id){const o=S.orders.find(x=>x.id===id),items=S.items.filter(i=>i.order_id===id);let h=table(['Producto','Cantidad','Subtotal'],items.map(i=>[esc(i.product_name),i.quantity,money(i.quantity*i.unit_cents)]))+'<h3 style="margin-top:20px">Total: '+money(o.total_cents)+'</h3><p>'+badge(o.status)+'</p>';if(o.sender)h+='<div class="account-data"><label>REMITENTE</label>'+esc(o.sender)+'<label>ID O CÓDIGO DE TRANSACCIÓN</label><code>'+esc(o.transaction_code||'No registrado (pedido anterior)')+'</code><label>FECHA E IMPORTE DECLARADOS</label>'+esc(o.payment_date)+' · '+money(o.paid_cents)+'<label>BANCO SELECCIONADO</label>'+esc(S.banks.find(b=>b.id===o.bank_id)?.bank||'—')+'</div>';if(o.note)h+='<p class="notice">'+esc(o.note)+'</p>';if(role()==='admin'&&o.status==='review')h+='<p class="notice">Verifica el ingreso en tu banco antes de aprobar. Esta acción entregará las cuentas al comprador.</p><div class="row-actions">'+btn('Pago recibido: entregar','order-approve',id,'success')+btn('Rechazar pago','order-reject',id,'danger')+'</div>';if(role()==='wholesale'&&o.status==='pending'){h+='<p class="notice">Transfiere el importe exacto. El stock queda reservado hasta 24 horas mientras no declares el pago. Una vez enviado a revisión, espera la aprobación.</p>'+S.banks.map(b=>'<div class="account-data"><strong>'+esc(b.bank)+'</strong><br>'+esc(b.holder)+'<br>'+esc(b.kind)+': '+esc(b.account_number)+'<br>'+esc(b.instructions)+'</div>').join('')+'<div class="row-actions">'+(S.banks.length?btn('Ya envié el dinero','payment',id,'primary'):'<p class="error">El administrador debe configurar una cuenta bancaria.</p>')+btn('Cancelar pedido','order-cancel',id,'ghost')+'</div>';}modal('Pedido #'+o.id.slice(0,8),h,null,false,{type:'order',id});}
function moneyInput(v){const n=Math.round(Number(v)*100);if(!Number.isSafeInteger(n)||n<0)throw Error('Importe no válido');return n;}
