function manageUserAccess(id,decision){const u=S.users.find(x=>x.id===id);if(!u||u.deleted_at)return;const title={suspend:'Suspender acceso',activate:'Reactivar acceso',delete:'Eliminar usuario'}[decision];const text=decision==='suspend'?'Se cerrará su acceso y no podrá iniciar sesión. Sus compras, cuentas, garantías y saldo se conservan. Puedes reactivarlo después.':decision==='activate'?'Podrá volver a iniciar sesión con su correo y contraseña. Las sesiones anteriores seguirán cerradas.':'Se quitará su acceso y desaparecerá de la lista de usuarios. El registro histórico se conserva para no borrar compras, pagos ni garantías. No se permite eliminarlo con saldo, retiros, pedidos o reportes pendientes; los trabajadores deben terminar sus cargas por revisar o corregir. Las garantías de trabajadores retirados pasan al administrador. Para un bloqueo temporal utiliza Suspender.';modal(title,'<p><strong>'+esc(u.name)+'</strong><br>'+esc(u.email)+'</p><div class="notice">'+text+'</div>'+(decision==='delete'?field('confirmation','Escribe ELIMINAR para confirmar'):''),async d=>{await api('/api/admin/user-access',{id,decision,confirmation:d.confirmation});await load();toast(decision==='delete'?'Usuario eliminado de la lista. Historial conservado.':decision==='suspend'?'Acceso suspendido':'Acceso reactivado');});const submit=$('#modal-form [type=submit]');submit.textContent=title;if(decision==='delete')submit.className='danger';}

